import{_ as i,a0 as u,w as p,s as a,ao as l,I as n,x as s,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"學習 Linux 是我們的愛情語言 | LCTT x X-CMD","titleTemplate":false,"description":"學習 Linux 是我們的愛情語言 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"學習 Linux 是我們的愛情語言 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"學習 Linux 是我們的愛情語言 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200214 Linux is our love language","title":"學習 Linux 是我們的愛情語言","tag":"202003","desc":""},"relativePath":"202003/20200214 Linux is our love language.md","filePath":"[post].md"}'),g={name:"202003/20200214 Linux is our love language.md"};function d(m,t,x,f,C,T){const r=u("Link");return p(),a("div",null,[t[23]||(t[23]=l('<h1 id="學習-linux-是我們的愛情語言" tabindex="-1">學習 Linux 是我們的愛情語言 <a class="header-anchor" href="#學習-linux-是我們的愛情語言" aria-label="Permalink to “學習 Linux 是我們的愛情語言”">​</a></h1><blockquote><p>當一個妻子教丈夫一些新技能的時候，他們都學到了比期待更多的東西。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202003/22/163819clzuy77dc4d7q8zu.jpg" alt=""></p><p>2019 年是我們 Cherry 家學習的一年。我是一個喜歡學習新技術的高級軟件工程師，並把學到的內容一起教給了我的丈夫 Chris。通過教給他一些我學到的東西，並讓他全程經歷我的技術演練文章，我幫助 Chris 學習到了新技術，使他能夠將自己的職業生涯更深入地轉向技術領域。而我學習到了新的方法，使我的演練和培訓材料更易於讓讀者理解。</p><p>在這篇文章中，我們來討論一下我們各自和彼此學習到了什麼東西，然後探討這對於我們的未來有何影響。</p><h3 id="向學生的提問" tabindex="-1">向學生的提問 <a class="header-anchor" href="#向學生的提問" aria-label="Permalink to “向學生的提問”">​</a></h3><p><strong>Jess：</strong> Chris，是什麼導致你想深入學習我的領域的技能呢？</p><p><strong>Chris：</strong> 主要目的是為了讓我事業更進一步。作為一個網絡工程師的經歷告訴我，現在的網絡專家已經不像以前一樣有價值了，我必須掌握更多的知識。由於網絡經常被認為是造成這些天程序中斷或出錯的原因，我想從開發人員的角度瞭解更多關於編寫應用程序的知識，以便於瞭解它們如何依賴網絡資源。</p><p><strong>Jess：</strong> 我首先教你什麼內容？你從中學到什麼？</p>',9)),n("p",null,[t[1]||(t[1]=n("strong",null,"Chris：",-1)),t[2]||(t[2]=s(" 首先是從學習除此安裝 Linux 系統開始的，之後又安裝了 ",-1)),e(r,{href:"https://opensource.com/resources/what-ansible"},{default:o(()=>[...t[0]||(t[0]=[s("Ansible",-1)])]),_:1}),t[3]||(t[3]=s("。只要硬件兼容，我用過的每一個 Linux 發行版都很容易安裝，但可能會出現個別不兼容的情況。這就意味着我有時候第一手學習到的是如何解決系統安裝過程的最初 5 分鐘出現的問題了（這個我最喜歡了）。Ansible 給了一個我學習使用軟件管理器來安裝程序的理由。當程序安裝完成後，通過查看 yum 安裝的程序，我快速瞭解了程序管理器是如何處理程序的依賴項的，因此，用 Python 編寫的 Ansible 能夠在我的系統運行。自此之後，我開始使用 Ansible 來安裝各種各樣的程序。",-1))]),t[24]||(t[24]=n("p",null,[n("strong",null,"Jessica："),s(" 你喜歡我這種教學方式不？")],-1)),t[25]||(t[25]=n("p",null,[n("strong",null,"Chris："),s(" 我們一開始有過爭吵，直到我們弄清楚了我喜歡的學習方式，你也知道了應該怎樣為我提供最好的學習方式。在一開始的時候，我很難跟上你講的內容。例如，當你説“一個碼頭工人集裝箱”的時候，我完全不知道你在講什麼。比較早的時候，我的回答就是“這是一個集裝箱”，然而當時這對我來説，完全沒有意義。當你對這些內容進行一些更深入的講解後，才讓學習更有趣。")],-1)),t[26]||(t[26]=n("p",null,[n("strong",null,"Jess："),s(" 老實説，這對我來説也是一個重要的教訓。在你之前，我從來沒有教過在這個技術領域知識比我少的人，所以你幫助我認識到我需要解釋更多細節。我也得説聲謝謝。")],-1)),t[27]||(t[27]=n("p",null,"當你通過這幾個學習步驟的時候，你覺得我的這篇測試文章怎樣呢？",-1)),n("p",null,[t[5]||(t[5]=n("strong",null,"Chris：",-1)),t[6]||(t[6]=s(" 就我個人而言，我認為這很容易，但我錯了。在我主要學習的內容中，比如你",-1)),e(r,{href:"https://opensource.com/resources/vagrant"},{default:o(()=>[...t[4]||(t[4]=[s("介紹的Vagrant",-1)])]),_:1}),t[7]||(t[7]=s("，它在不同的 Linux 發行版間的變化比我想像的要多。操作系統的變化會影響設置的方式、運行都要求和特定的命令。這看起來比我用的網絡設備變化更大。這讓我花費更多的精力去查看這些説明是對應我的系統還是其它的系統（有時候很難知道）。在這學習路上，我似乎碰到很多問題。",-1))]),t[28]||(t[28]=l('<p><strong>Jess：</strong> 我每天都會遇到各種各樣的問題，所以對我來説日常就是用各種方法解決各種問題。</p><h3 id="向老師的提問" tabindex="-1">向老師的提問 <a class="header-anchor" href="#向老師的提問" aria-label="Permalink to “向老師的提問”">​</a></h3><p><strong>Chris：</strong> Jess，你將來教我的方式會有所改變嗎？</p><p><strong>Jess：</strong> 我想讓你像我一樣讀多一些書。通過翻閲書籍來學習新技術。每天起牀後一小時和睡覺前一小時我都會看書，花費一個星期左右我就能看一到兩本書。我也會創建為期兩週的任務計劃來實踐我從書本中學習到的技能。這是除了我一天中第一個小時在喝大量咖啡時讀到的科技文章之外的。當我考慮到你的職業發展目標的時候，我認為除了我們談到的優秀Blog文章和文章之外，書籍是一個重要的元素。我覺得我的閲讀量使我保持進步，如果你也這麼做了，你也會很快趕上我的。</p><p><strong>Chris：</strong> 那麼學生有沒有教過老師呢？</p><p><strong>Jess：</strong> 我在你那裏學習到耐心。舉個例子，當你完成了安裝 Ansible 的時候，我問你下一步要怎樣操作的時候。你直接回復我，“不知道”，這不是我想讓你學習到的內容。所以我改變了策略，現在在逐步安裝任何組件之前，我們將詳細討論你想要實現的目標。當我們在寫 Vagrant 文章的時候，我們一起進行相應的演示操作，我以創建它時就牢記目標，因此我們就有一些需要馬上實現的目標。</p><p>這實際上對我在工作中的培訓方式產生了巨大的改變。現在我在大家學習的過程中會問更多問題，並更多地進行手把手講解。我更願意坐下來仔細檢查，確保有人明白我在説什麼和我們在做什麼。這是我之前從來沒有做過的。</p><h3 id="我們一起學到了什麼" tabindex="-1">我們一起學到了什麼 <a class="header-anchor" href="#我們一起學到了什麼" aria-label="Permalink to “我們一起學到了什麼”">​</a></h3><p>做為一對夫婦，在這一年的技術合作中我們的技術都有所增長。</p><p><strong>Chris：</strong> 我對自己學到的東西感到震驚。通過一年課程學習，我認識了新操作系統、如何使用 API、使用 Ansible 部署 Web 應用和使用 Vagrant 啓動虛擬機器。我還學習到了文檔可以讓生活變得更好，所以我也會嘗試去寫一寫。然而，在這個工作領域，操作並不總是被記錄在案，所以我學會了準備好處理棘手的問題，並記錄如何解決它們。</p><p><strong>Jess：</strong> 除了我在教你中學到的知識外，我還專注於學習 Kubernetes 在雲環境中的應用知識。這包括部署策略、Kubernetes API 的複雜度、創建我自己的容器，並對環境進行加密處理。我還節省了探索的時間：研究了 serverless 的代碼、AI 模型、Python 和以圖形方式顯示熱圖。對於我來説，這一年也很充足。</p><p>我們下一個目標是什麼？現在還不知道，但我可以向你保證，我們將會繼續進行分享它。</p><hr>',13)),n("p",null,[t[9]||(t[9]=s("via: ",-1)),e(r,{href:"https://opensource.com/article/20/2/linux-love-language"},{default:o(()=>[...t[8]||(t[8]=[s("https://opensource.com/article/20/2/linux-love-language",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=s("作者：",-1)),e(r,{href:"https://opensource.com/users/chcherry"},{default:o(()=>[...t[10]||(t[10]=[s("Christopher Cherry",-1)])]),_:1}),t[15]||(t[15]=s(" 選題：",-1)),e(r,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[11]||(t[11]=[s("lujun9972",-1)])]),_:1}),t[16]||(t[16]=s(" 譯者：",-1)),e(r,{href:"https://github.com/sndnvaps"},{default:o(()=>[...t[12]||(t[12]=[s("sndnvaps",-1)])]),_:1}),t[17]||(t[17]=s(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[13]||(t[13]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=s("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[18]||(t[18]=[s("LCTT",-1)])]),_:1}),t[21]||(t[21]=s(" 原創編譯，",-1)),e(r,{href:"https://linux.cn/"},{default:o(()=>[...t[19]||(t[19]=[s("Linux中國",-1)])]),_:1}),t[22]||(t[22]=s(" 榮譽推出",-1))])])}const P=i(g,[["render",d]]);export{A as __pageData,P as default};
